mber" min="2000" max="2150" name="graduation_year" value="<?=e((string)($profile['graduation_year']??''))?>"></label></div></div><label>About you<textarea class="form-control" name="bio" rows="4" maxlength="3000" placeholder="A short professional introduction"><?=e((string)($profile['bio']??''))?></textarea></label><button class="primary-btn" type="submit">Save profile ↗</button></form></section><section class="panel mt-4"><h2>Skills</h2><p class="muted">Enter skills separated by commas. Skill names are normalized by trimming whitespace; this form does not claim verification.</p><form method="post" class="auth-form"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_skills"><label>Your skills<textarea class="form-control" name="skills" rows="3" maxlength="2000" placeholder="PHP, MySQL, JavaScript, Git"><?=e(implode(', ',$profileSkills??[]))?></textarea></label><button class="primary-btn" type="submit">Save skills ↗</button></form></section><?php endif; ?></main>
<?php elseif($page==='jobs' && $user && $user['role']==='student'): ?><main class="dashboard container"><div class="dash-top"><div><p class="eyebrow">STUDENT WORKSPACE</p><h1>Open opportunities.</h1><p class="muted">Only published jobs from approved companies are shown. Academic checks are mandatory.</p></div><a class="secondary-btn" href="index.php?page=applications">My applications</a></div><?php if(!empty($jobsError)): ?><div class="empty-state">Jobs could not be loaded. Check database setup.</div><?php elseif(empty($jobs)): ?><div class="empty-state mt-4"><h2>No open jobs yet</h2><p>Approved companies have not published any current opportunities. No sample jobs are created.</p></div><?php else: ?><div class="row g-3 mt-2"><?php foreach($jobs as $job): ?><div class="col-12"><article class="panel"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><p class="eyebrow"><?=e($job['company_name'])?></p><h2><?=e($job['title'])?></h2><p class="muted"><?=e($job['location']??'Location not specified')?> · <?=e($job['employment_type']??'Employment type not specified')?></p></div><span class="status-pill">Minimum CGPA: <?=e((string)$job['min_cgpa'])?></span></div><p><?=nl2br(e($job['description']))?></p><?php if($job['eligible_branch']): ?><p class="muted">Eligible branch: <?=e($job['eligible_branch'])?></p><?php endif; ?><?php if(in_array((int)$job['id'],$appliedJobIds,true)): ?><span class="status-pill">Application submitted</span><?php else: ?><form method="post" class="auth-form"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="apply_job"><input type="hidden" name="job_id" value="<?=(int)$job['id']?>"><label>Optional note to recruiter<textarea class="form-control" name="cover_note" maxlength="2000" rows="2"></textarea></label><button class="primary-btn" type="submit">Apply now ↗</button></form><?php endif; ?></article></div><?php endforeach; ?></div><?php endif; ?></main>
<?php elseif($page==='applications' && $user && $user['role']==='student'): ?><main class="dashboard container"><div class="dash-top"><div><p class="eyebrow">STUDENT WORKSPACE</p><h1>Your applications.</h1><p class="muted">Track status updates for jobs you've applied to.</p></div><a class="secondary-btn" href="index.php?page=jobs">Browse jobs</a></div><?php if(!empty($applicationsError)): ?><div class="empty-state">Applications could not be loaded. Check database setup.</div><?php elseif(empty($applications)): ?><div class="empty-state mt-4"><h2>No applications yet</h2><p>When you apply to an open job, its current status will appear here.</p></div><?php else: ?><div class="panel mt-4 table-responsive"><table class="table table-dark table-hover align-middle"><thead><tr><th>Role</th><th>Company</th><th>Applied</th><th>Status</th></tr></thead><tbody><?php foreach($applications as $app): ?><tr><td><?=e($app['title'])?><div class="muted"><?=e($app['location']??'')?></div></td><td><?=e($app['company_name'])?></td><td><?=e($app['applied_at'])?></td><td><span class="status-pill"><?=e(ucwords(str_replace('_',' ',$app['status'])))?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main>
